/*
 * A204504  A204512(n)^2 = floor[A055872(n)/8]: Squares such that appending
 *          some digit in base 8 yields another square.
 * https://oeis.org/A204504
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   a(1) = a(2) = a(3) = 0. For n ≥ 4, let k = n – 4. If k is even,
 *            a(n) = (b1[k/2])². If k is odd, a(n) = (b2[(k–1)/2])². The
 *            sequences b1 and b2 are generated by the linear recurrence
 *            b_{m+1} = 6·b_m – b_{m‑1} with initial values b1 : 1, 6, 35,
 *            204, … b2 : 2, 12, 70, 408, … These are exactly the in...
 * Range:     u8 n <= 7, u16 n <= 10, u32 n <= 16, u64 n <= 26, u128 n <= 26,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

/* ---------- internal storage for the two Pell‑type sequences ---------- */
static seq_t *b1  = NULL;  /* sequence for x² – 8y² = 1      */
static idx_t len_b1 = 0;   /* number of elements stored      */
static idx_t cap_b1 = 0;   /* allocated capacity             */

static seq_t *b2  = NULL;  /* sequence for x² – 8y² = 4      */
static idx_t len_b2 = 0;
static idx_t cap_b2 = 0;

/* ---------- helpers -------------------------------------------------- */
static void init_b1(void)
{
    if (b1) return;
    cap_b1 = 2;
    b1   = (seq_t *)malloc(cap_b1 * sizeof(seq_t));
    if (!b1) exit(1);
    b1[0] = 1;               /* b1[0] = 1  */
    b1[1] = 6;               /* b1[1] = 6  */
    len_b1 = 2;
}

static void init_b2(void)
{
    if (b2) return;
    cap_b2 = 2;
    b2   = (seq_t *)malloc(cap_b2 * sizeof(seq_t));
    if (!b2) exit(1);
    b2[0] = 2;               /* b2[0] = 2  */
    b2[1] = 12;              /* b2[1] = 12 */
    len_b2 = 2;
}

static void grow_b1(idx_t need)
{
    init_b1();
    while (len_b1 <= need) {
        if (len_b1 >= cap_b1) {          /* double capacity */
            size_t new_cap = cap_b1 * 2;
            seq_t *tmp = (seq_t *)realloc(b1, new_cap * sizeof(seq_t));
            if (!tmp) exit(1);
            b1 = tmp;
            cap_b1 = new_cap;
        }
        /* recurrence: b_{m+1} = 6*b_m – b_{m-1} */
        seq_t next = b1[len_b1-1] * 6;
        next -= b1[len_b1-2];
        b1[len_b1] = next;
        len_b1++;
    }
}

static void grow_b2(idx_t need)
{
    init_b2();
    while (len_b2 <= need) {
        if (len_b2 >= cap_b2) {
            size_t new_cap = cap_b2 * 2;
            seq_t *tmp = (seq_t *)realloc(b2, new_cap * sizeof(seq_t));
            if (!tmp) exit(1);
            b2 = tmp;
            cap_b2 = new_cap;
        }
        seq_t next = b2[len_b2-1] * 6;
        next -= b2[len_b2-2];
        b2[len_b2] = next;
        len_b2++;
    }
}

/* ---------- required sequence function ------------------------------- */
seq_t a(idx_t n)
{
    if (n <= 3) return (seq_t)0;   /* first three terms are zero */

    idx_t k = n - 4;
    if ((k & 1) == 0) {                /* even offset: use b1 */
        idx_t i = k >> 1;
        grow_b1(i);
        seq_t v = b1[i];
        return v * v;
    } else {                            /* odd offset: use b2 */
        idx_t i = (k - 1) >> 1;
        grow_b2(i);
        seq_t v = b2[i];
        return v * v;
    }
}
